const CACHE='knowledge-park-v23-winter';
const scripts=["path-routes", "glow-pass", "activity-reactions", "activity-state", "alpine-resort", "app", "audio-engine", "audio-world", "aurora-landmarks", "bumper-physics", "carousel-horse-geometry", "carousel-model", "character-accessories", "community-ui", "companion", "connected-terrain", "conservatory-layout", "decorations", "discovery", "effects", "emotes", "fantasy-vfx", "festival-layout", "festival-rides", "footprints", "game-input", "interior-layout", "interior-world", "learning-core", "light-duet", "loading-state", "movement", "navigation", "panels", "park", "park-details", "park-lamps", "park-layout", "preview-orbit", "quick-quiz", "resort-layout", "resort-scenery", "retreat-layout", "shared-tree", "simulations", "skate-effects", "skating", "ski-trails", "snow-path", "social", "spa-experience", "spa-resort", "studio", "themepark-world", "tree-ornaments", "trivia-fallback", "trivia-loader", "ui-motion", "vfx-shaders", "visitors", "wardrobe", "weather-clock", "winter-costumes", "winter-experience", "winter-music", "winter-retreat", "winter-rides", "winter-sky", "winter-world", "world-art", "world-guide-data", "world-interactions", "world-labels", "world-layout", "world-map", "world-paths", "world-time"];
const CORE=['./','./index.html','./style.css?v=winter23','./soft.css?v=winter23','./winter.css?v=winter23','./aurora.css?v=winter23','./metaverse.css?v=winter23','./vendor/three.module.js',...scripts.flatMap(n=>['./'+n+'.js','./'+n+'.js?v=winter23']),...['science','reasoning','humanities','perspectives','everyday','daily-trivia'].map(n=>'./content/'+n+'.json')];
const assetPaths=new Set(CORE.map(p=>new URL(p,self.location.href).pathname));
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(CORE)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>(key.startsWith('knowledge-campus-')||key.startsWith('knowledge-park-'))&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||!assetPaths.has(url.pathname))return;event.respondWith(fetch(event.request).then(async response=>{if(response.ok&&!response.redirected){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy)).catch(()=>{});}if(response.status>=500)return(await caches.match(event.request))||response;return response;}).catch(async()=>{const cached=await caches.match(event.request);return cached||new Response('연결을 확인하고 다시 시도해 주세요.',{status:503});}));});
